    /**
     * 所属项目
     */
    projectId: number;
    /**
     * 工作流类型
     */
    workflowType: string;
    /**
     * 用户目标
     */
    goal: string;
    /**
     * 当前实际状态
     */
    status: 'queued' | 'running' | 'waiting_compute' | 'waiting_approval' | 'paused' | 'succeeded' | 'failed' | 'cancelled' | 'interrupted';
    /**
     * 可读状态
     */
    detail: string;
    /**
     * 当前节点
     */
    currentStep: string;
    /**
     * 创建时间
     */
