    /**
     * 授权输入资源 ID
     */
    resourceIds: Array<number>;
    /**
     * 固定算法版本 ID
     */
    algorithmVersionId: number | null;
    /**
     * 已校验参数
     */
    parameters: {
        [key: string]: unknown;
    };
    /**
     * 结果引用 ID
     */
