    /**
     * 后端根据业务类型、字段命中结果和字段统计推荐的矢量符号化模板。前端可直接预览并应用其中的 `symbolization`，保存仍沿用现有自定义符号化权限。
     */
    recommendedSymbolizations: Array<RecommendedSymbolizationTemplate>;
